def remove_adjacent_duplicates(lst):
    # your code here
    if not lst:
        return []
    res = [lst[0]]
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            res.append(lst[i])
    return res

class TestRemoveAdjacentDuplicates(unittest.TestCase):
    def test_basic_functionality(self):
        self.assertEqual(remove_adjacent_duplicates([1, 2, 2, 3, 3, 3, 4]), [1, 2, 3, 4])

    def test_repeated_elements(self):
        self.assertEqual(remove_adjacent_duplicates([5, 5, 5, 6, 7, 7]), [5, 6, 7])

    def test_multiple_duplicates(self):
        self.assertEqual(remove_adjacent_duplicates([1, 2, 3, 4, 4, 4, 4, 5, 5]), [1, 2, 3, 4, 5])

    def test_empty_list(self):
        self.assertEqual(remove_adjacent_duplicates([]), [])

    def test_single_element(self):
        self.assertEqual(remove_adjacent_duplicates([4]), [4])

    def test_no_duplicates(self):
        self.assertEqual(remove_adjacent_duplicates([1, 2, 3]), [1, 2, 3])

    def test_all_same_elements(self):
        self.assertEqual(remove_adjacent_duplicates([7, 7, 7]), [7])

    def test_alternating_elements(self):
        self.assertEqual(remove_adjacent_duplicates([1, 2, 1, 3, 1, 2, 1]), [1, 2, 1, 3, 1, 2, 1])

if __name__ == '__main__':
    unittest.main()

